-- Supervised cooking: snapshots, contribution ledger and deferred refunds.
alter table public.cozy_projects add column if not exists owner_id uuid;
alter table public.cozy_projects add column if not exists menu jsonb;
alter table public.cozy_projects add column if not exists last_pulse numeric;
alter table public.cozy_projects add column if not exists remaining numeric not null default 1800;
alter table public.cozy_projects add column if not exists complete_at numeric;
alter table public.cozy_projects add column if not exists canceled_at numeric;
alter table public.cozy_projects add column if not exists ledger jsonb not null default '[]';
create index if not exists cozy_projects_owner on public.cozy_projects(owner_id);
create index if not exists cozy_projects_scope on public.cozy_projects(scope);
create index if not exists cozy_projects_contributors on public.cozy_projects using gin(contributors);
-- The previous prototype used one project per scope. Multiple preparations are approved.
alter table public.cozy_projects drop constraint if exists cozy_projects_scope_key;
create table if not exists public.cozy_refunds(project_id uuid not null,recipient uuid not null references public.characters(id) on delete cascade,sequence int not null,item jsonb not null,primary key(project_id,recipient,sequence));
alter table public.cozy_refunds enable row level security;
revoke all on table public.cozy_refunds from public,anon,authenticated;

create table if not exists public.meal_daily_menus(character_id uuid not null references public.characters(id) on delete cascade,day text not null,rank int not null,menu jsonb not null,primary key(character_id,day,rank));
alter table public.meal_daily_menus enable row level security;
revoke all on table public.meal_daily_menus from public,anon,authenticated;
create or replace function public.game_meal_menu(cid uuid,d jsonb,stamp numeric) returns jsonb language plpgsql volatile security definer set search_path='' as $$
<<menus>>
declare pool jsonb;result jsonb:='[]';cached jsonb;i int;offset_at int;rank int:=public.game_rpg_rank(d->'rpg','cocina');day text:=to_char(to_timestamp(stamp) at time zone 'UTC','YYYY-MM-DD');
begin
 select m.menu into cached from public.meal_daily_menus m where m.character_id=cid and m.day=menus.day and m.rank=menus.rank;
 if cached is not null then return cached;end if;
 delete from public.meal_daily_menus where character_id=cid and meal_daily_menus.day<to_char((to_timestamp(stamp) at time zone 'UTC')-interval '7 days','YYYY-MM-DD');
 select jsonb_agg(value order by key collate "C") into pool from jsonb_each(public.game_rpg_catalog()->'meals') where (value->>'tier')::int=rank;
 if pool is null then return result;end if;
 offset_at:=(public.game_cozy_hash(cid::text)+floor(stamp/86400)::bigint*3)%jsonb_array_length(pool);
 for i in 0..least(2,jsonb_array_length(pool)-1) loop result:=result||jsonb_build_array(pool->((offset_at+i)%jsonb_array_length(pool)));end loop;
 insert into public.meal_daily_menus(character_id,day,rank,menu) values(cid,menus.day,menus.rank,result) on conflict do nothing;
 select m.menu into result from public.meal_daily_menus m where m.character_id=cid and m.day=menus.day and m.rank=menus.rank;
 return result;
end $$;
create or replace function public.game_meal_cancel(project uuid,stamp numeric) returns void language plpgsql volatile security definer set search_path='' as $$
declare p public.cozy_projects;entry record;
begin
 select * into p from public.cozy_projects where id=project for update;
 if p.id is null or p.complete_at is not null or p.canceled_at is not null or p.menu is null then return;end if;
 update public.cozy_projects set canceled_at=stamp where id=project;
 for entry in select value,ordinality from jsonb_array_elements(p.ledger) with ordinality loop
  insert into public.cozy_refunds(project_id,recipient,sequence,item) values(project,(entry.value->>'character')::uuid,entry.ordinality,entry.value->'item') on conflict do nothing;
 end loop;
end $$;
create or replace function public.game_meals_tick(stamp numeric,cid uuid) returns void language plpgsql volatile security definer set search_path='' as $$
declare p public.cozy_projects;party uuid;active_until numeric;elapsed numeric;left_time numeric;
begin
 select party_id into party from public.party_members where character_id=cid;
 for p in select * from public.cozy_projects where menu is not null and complete_at is null and canceled_at is null
  and (owner_id=cid or contributors ? cid::text or scope='party:'||party::text) order by id for update loop
  if p.scope like 'party:%' and not exists(select 1 from public.parties where id=substr(p.scope,7)::uuid) then perform public.game_meal_cancel(p.id,stamp);continue;end if;
  select max(least(stamp,extract(epoch from w.seen_at)+15)) into active_until from public.world_players w
   where w.character_id=p.owner_id or p.contributors ? w.character_id::text or exists(select 1 from public.party_members pm where pm.character_id=w.character_id and 'party:'||pm.party_id::text=p.scope);
  elapsed:=greatest(0,coalesce(active_until,p.last_pulse)-coalesce(p.last_pulse,stamp));left_time:=greatest(0,p.remaining-elapsed);
  update public.cozy_projects set remaining=left_time,last_pulse=stamp where id=p.id;
  if left_time=0 then perform public.game_meal_cancel(p.id,stamp);end if;
 end loop;
end $$;
create or replace function public.game_meal_mail(cid uuid,d jsonb) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare r record;s jsonb:=coalesce(d->'rpg','{}');deliveries jsonb:=coalesce(s->'deliveries','[]');
begin
 for r in select * from public.cozy_refunds where recipient=cid order by project_id,sequence for update loop
  deliveries:=deliveries||jsonb_build_array(r.item);delete from public.cozy_refunds where project_id=r.project_id and recipient=cid and sequence=r.sequence;
 end loop;
 return d||jsonb_build_object('rpg',s||jsonb_build_object('deliveries',deliveries));
end $$;
create or replace function public.game_presence_cozy_clock() returns trigger language plpgsql volatile security definer set search_path='' as $$
declare stamp numeric:=extract(epoch from clock_timestamp());elapsed numeric;
begin
 if TG_OP<>'INSERT' then
  perform public.game_meals_tick(stamp,old.character_id);
  elapsed:=greatest(0,least(case when TG_OP='DELETE' then stamp else extract(epoch from new.seen_at) end,extract(epoch from old.seen_at)+15)-extract(epoch from old.seen_at));
  if exists(select 1 from public.characters c cross join lateral jsonb_array_elements(coalesce(c.data->'rpg'->'jobs','[]')) j where c.id=old.character_id and not coalesce((j->>'done')::boolean,false)) then
   insert into public.craft_activity(character_id,online_seconds) values(old.character_id,elapsed) on conflict(character_id) do update set online_seconds=public.craft_activity.online_seconds+excluded.online_seconds;
  end if;
 end if;
 if TG_OP<>'DELETE' then
  if TG_OP='INSERT' or new.character_id is distinct from old.character_id then perform public.game_meals_tick(stamp,new.character_id);end if;
  return new;
 end if;
 return old;
end $$;
drop trigger if exists presence_cozy_clock on public.world_players;
create trigger presence_cozy_clock before insert or update of seen_at,character_id or delete on public.world_players for each row execute function public.game_presence_cozy_clock();
create or replace function public.game_party_cancel_meals() returns trigger language plpgsql volatile security definer set search_path='' as $$
declare p record;begin
 for p in select id from public.cozy_projects where scope='party:'||old.id::text and complete_at is null and canceled_at is null and menu is not null order by id loop perform public.game_meal_cancel(p.id,extract(epoch from clock_timestamp()));end loop;
 return old;
end $$;
drop trigger if exists party_cancel_meals on public.parties;
create trigger party_cancel_meals before delete on public.parties for each row execute function public.game_party_cancel_meals();

create or replace function public.game_meal_action(cid uuid,d jsonb,action text,args jsonb,pos jsonb,stamp numeric) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare p public.cozy_projects;party uuid;scope_id text;leader uuid;teacher jsonb:=public.game_rpg_catalog()->'teachers'->'cocina';cfg jsonb;day text:=to_char(to_timestamp(stamp) at time zone 'UTC','YYYY-MM-DD');s jsonb:=d->'rpg';q jsonb;inv jsonb;item jsonb;consumed jsonb;idx int;needed int;amount int;entry record;rewardable boolean;done boolean;
begin
 if args->>'master' is distinct from teacher->>'id' or d->>'location' is distinct from teacher->>'location' or sqrt(power((pos->>'x')::numeric-(teacher->>'x')::numeric,2)+power((pos->>'z')::numeric-(teacher->>'z')::numeric,2))>3 then raise exception 'Habla con el maestro de Cocina.';end if;
 perform public.game_meals_tick(stamp,cid);d:=public.game_meal_mail(cid,d);s:=d->'rpg';
 select party_id into party from public.party_members where character_id=cid;scope_id:=coalesce('party:'||party::text,'character:'||cid::text);
 q:=case when s->'mealQuota'->>'day'=day then s->'mealQuota' else jsonb_build_object('day',day,'completed',0) end;
 if action='meal_start' then
  if party is not null then select character_id into leader from public.party_members where party_id=party order by entry_order limit 1;if leader<>cid then raise exception 'El líder elige la receta de su menú.';end if;end if;
  if (select count(*) from public.cozy_projects where menu is not null and canceled_at is null and complete_at is null and (owner_id=cid or contributors ? cid::text))>=3 then raise exception 'Ya tienes tres preparaciones pendientes.';end if;
  select value into cfg from jsonb_array_elements(public.game_meal_menu(cid,d,stamp)) where value->>'id'=args->>'id';
  if cfg is null then raise exception 'Elige una receta de tu menú de hoy.';end if;
  cfg:=cfg||jsonb_build_object('pelines',(cfg->>'difficulty')::int*10,'xp',(cfg->>'difficulty')::int*5,'count',1);
  insert into public.cozy_projects(scope,owner_id,menu,last_pulse) values(scope_id,cid,cfg,stamp);
 elsif action in('neighbor_contribute','meal_contribute') then
  select * into p from public.cozy_projects where id=(args->>'project')::uuid for update;
  if p.id is null or p.scope<>scope_id or p.canceled_at is not null or p.complete_at is not null then raise exception 'Preparación no disponible.';end if;
  if not(p.contributors ? cid::text) and p.owner_id<>cid and (select count(*) from public.cozy_projects where menu is not null and canceled_at is null and complete_at is null and (owner_id=cid or contributors ? cid::text))>=3 then raise exception 'Ya tienes tres preparaciones pendientes.';end if;
  needed:=(p.menu->'ingredients'->>(args->>'id'))::int;
  if needed is null or coalesce((p.ingredients->>(args->>'id'))::int,0)>=needed then raise exception 'Este ingrediente ya está completo o no forma parte de la receta.';end if;
  rewardable:=coalesce((q->>'completed')::int,0)<2;
  if not rewardable and not coalesce((args->>'help')::boolean,false) then raise exception 'Ya has cobrado dos meriendas. Confirma que quieres ayudar sin recompensa.';end if;
  inv:=public.game_inventory(d);
  for idx in 0..24 loop item:=inv->idx;if item->>'id'=args->>'id' and not coalesce((item->>'bound')::boolean,false) then consumed:=item||'{"count":1}';inv:=jsonb_set(inv,array[idx::text],case when (item->>'count')::int=1 then 'null'::jsonb else item||jsonb_build_object('count',(item->>'count')::int-1) end);exit;end if;end loop;
  if consumed is null then raise exception 'Falta el ingrediente en la mochila.';end if;
  p.ingredients:=jsonb_set(p.ingredients,array[args->>'id'],to_jsonb(coalesce((p.ingredients->>(args->>'id'))::int,0)+1));
  done:=not exists(select 1 from jsonb_each_text(p.menu->'ingredients') where coalesce((p.ingredients->>key)::int,0)<value::int);
  update public.cozy_projects set ingredients=p.ingredients,contributors=case when contributors ? cid::text then contributors else contributors||jsonb_build_array(cid) end,
   ledger=ledger||jsonb_build_array(jsonb_build_object('character',cid,'item',consumed,'rewardable',rewardable)),remaining=1800,last_pulse=stamp,complete_at=case when done then stamp end where id=p.id;
  d:=d||jsonb_build_object('inventory',inv);
 elsif action in('neighbor_claim','meal_claim') then
  select * into p from public.cozy_projects where id=(args->>'id')::uuid for update;
  if p.id is null or p.complete_at is null or p.canceled_at is not null or p.claimed ? cid::text or not(p.contributors ? cid::text) then raise exception 'No tienes recompensa pendiente de esta preparación.';end if;
  if stamp>=p.complete_at+604800 then raise exception 'La recompensa ha caducado tras siete días.';end if;
  if coalesce((q->>'completed')::int,0)>=2 then raise exception 'Ya has cobrado dos meriendas hoy.';end if;
  if not exists(select 1 from jsonb_array_elements(p.ledger) where value->>'character'=cid::text and (value->>'rewardable')::boolean) then raise exception 'Esta aportación era ayuda sin recompensa.';end if;
  d:=public.game_rpg_give(d,public.game_rpg_new_item(p.menu->>'output',coalesce((p.menu->>'count')::int,1)),true);s:=d->'rpg';
  d:=public.game_set_pelines(d,public.game_pelines(d)+(p.menu->>'pelines')::int);
  s:=jsonb_set(s,array['xp','cocina'],to_jsonb(coalesce((s->'xp'->>'cocina')::int,0)+(p.menu->>'xp')::int));
  s:=s||jsonb_build_object('mealQuota',q||jsonb_build_object('completed',coalesce((q->>'completed')::int,0)+1));d:=d||jsonb_build_object('rpg',s);
  update public.cozy_projects set claimed=claimed||jsonb_build_array(cid) where id=p.id;
 else raise exception 'No se permite cancelar manualmente una merienda.';end if;
 return d;
end $$;
create or replace function public.game_meal_view(cid uuid,stamp numeric) returns jsonb language sql stable security definer set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'active',p.canceled_at is null and p.complete_at is null,'ingredients',p.ingredients,'recipe',p.menu,'remaining',p.remaining,'complete',p.complete_at is not null,'expiresAt',p.complete_at+604800,'contributors',jsonb_array_length(p.contributors),'contributed',p.contributors ? cid::text,'claimed',p.claimed ? cid::text,'rewardable',exists(select 1 from jsonb_array_elements(p.ledger) where value->>'character'=cid::text and (value->>'rewardable')::boolean)) order by p.id),'[]')
 from public.cozy_projects p where p.menu is not null and p.canceled_at is null and (p.complete_at is null or stamp<p.complete_at+604800) and
 (p.owner_id=cid or p.contributors ? cid::text or exists(select 1 from public.party_members pm where pm.character_id=cid and p.scope='party:'||pm.party_id::text))
$$;
revoke all on function public.game_meal_cancel(uuid,numeric),public.game_meals_tick(numeric,uuid),public.game_meal_mail(uuid,jsonb),public.game_presence_cozy_clock(),public.game_party_cancel_meals(),public.game_meal_action(uuid,jsonb,text,jsonb,jsonb,numeric),public.game_meal_view(uuid,numeric),public.game_meal_menu(uuid,jsonb,numeric) from public,anon,authenticated;

-- An automatic offline cleanup must not dissolve a paused cooking group.
-- Explicitly leaving/disbanding still follows the normal party rules.
create or replace function public.game_party_cleanup() returns void language plpgsql security definer set search_path='' as $$
begin
 perform pg_catalog.pg_advisory_xact_lock(731029,2);
 delete from public.party_responses where created_at<=now()-interval '5 minutes';
 delete from public.party_members m where not exists(select 1 from public.world_players w where w.user_id=m.user_id and w.character_id=m.character_id and w.seen_at>now()-interval '15 seconds')
  and not exists(select 1 from public.cozy_projects p where p.scope='party:'||m.party_id::text and p.menu is not null and p.complete_at is null and p.canceled_at is null);
 delete from public.party_invites i where i.expires_at<=now() or exists(select 1 from public.party_members m where m.user_id=i.target_user)
  or not exists(select 1 from public.world_players w where w.user_id=i.target_user and w.seen_at>now()-interval '15 seconds');
 delete from public.parties p where not exists(select 1 from public.party_members m where m.party_id=p.id);
end $$;
revoke all on function public.game_party_cleanup() from public,anon,authenticated;

create or replace function public.rpg_action(p_character_id uuid,p_action text,p_args jsonb default '{}',p_request uuid default null,p_revision bigint default 0)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
 c public.characters; w public.world_players;d jsonb;s jsonb; catalog jsonb:=public.game_rpg_catalog();
 stamp numeric:=extract(epoch from clock_timestamp());id text:=coalesce(p_args->>'id','');job text:=coalesce(p_args->>'job','');
 item jsonb;meta jsonb;recipe jsonb;task jsonb;jobs jsonb;newjobs jsonb;entry record;outitem jsonb;inv jsonb;tool jsonb;
 slot int;idx int;n int;amount int;rank int;tier int;xp int;next_rank int;cost numeric;start_at numeric;duration numeric;cursor_at numeric;
 energy numeric;max_d numeric;original numeric;current_d numeric;loss numeric;fraction numeric;mat text;receipt jsonb;count_jobs int;px numeric;pz numeric;yaw numeric;
begin
 if auth.uid() is null then raise exception 'NOT_AUTHENTICATED';end if;
 perform pg_catalog.pg_advisory_xact_lock(731029,3);
 c:=public.game_lock_character(p_character_id);d:=public.game_rpg_settle(jsonb_set(c.data,'{rpg}',coalesce(c.data->'rpg','{}')||jsonb_build_object('owner',c.id)),stamp);s:=d->'rpg';
 s:=s||jsonb_build_object('bankAvailable',public.game_craft_bank(c.id));d:=d||jsonb_build_object('rpg',s);
 d:=public.game_meal_mail(c.id,d);s:=d->'rpg';
 if p_action='state' then return public.game_store(c.id,d);end if;
 if p_request is null then raise exception 'REQUEST_REQUIRED';end if;
 if coalesce(s->'requests','[]') ? p_request::text then return public.game_store(c.id,d);end if;
 if coalesce((s->>'revision')::bigint,0)<>p_revision then raise exception 'Tus oficios han cambiado. Actualiza la ventana.';end if;
 if public.game_health(d)=0 then raise exception 'Debes estar vivo.';end if;
 select * into w from public.world_players where character_id=c.id and user_id=auth.uid() and seen_at>now()-interval '15 seconds' for update;
 if not found then raise exception 'Entra en el mundo para realizar esta acción.';end if;
 -- Always use validated presence, never client-submitted positions.
 d:=d||jsonb_build_object('position',w.position);
 if p_action not in('state','gather_cancel') and d->'combatEncounter'->>'status'='active' and coalesce((d->'combatEncounter'->>'engaged')::boolean,false) then raise exception 'No puedes realizar esta acción durante el combate.';end if;
 if p_args ? 'slot' then slot:=(p_args->>'slot')::int;if slot not between 0 and 1000 then raise exception 'INVALID_SLOT';end if;end if;
 rank:=public.game_rpg_rank(s,job);

 if p_action='learn' then raise exception 'Habla con el maestro del oficio para aprender recetas.';
 elsif p_action like 'home\_%' escape '\' or p_action like 'neighbor\_%' escape '\' or p_action like 'meal\_%' escape '\' or p_action='tutorial_supply' then
  d:=public.game_cozy_action(c.id,d,p_action,p_args,w.position,stamp);s:=d->'rpg';
 elsif p_action in('tutorial_accept','tutorial_visit','tutorial_complete') then
  d:=public.game_profession_tutorial_action(d,p_action,p_args,w.position,stamp);s:=d->'rpg';
 elsif p_action like 'order\_%' escape '\' or p_action='daily_order' then
  d:=public.game_order_action(c.id,d,p_action,p_args,w.position,stamp);s:=d->'rpg';
 elsif p_action='buy_recipe' then
  recipe:=catalog->'recipes'->id;
  if recipe is null or public.game_rpg_rank(s,recipe->>'job')<(recipe->>'tier')::int then raise exception 'No tienes el dominio necesario.';end if;
  meta:=catalog->'teachers'->(recipe->>'job');
  if meta is null or meta->>'id' is distinct from p_args->>'master' or meta->>'location' is distinct from d->>'location'
   or sqrt(power((w.position->>'x')::numeric-(meta->>'x')::numeric,2)+power((w.position->>'z')::numeric-(meta->>'z')::numeric,2))>coalesce((meta->>'radius')::numeric,3) then raise exception 'Habla con el maestro de este oficio.';end if;
  if s->'learned' ? id then raise exception 'Ya conoces esta receta.';end if;
  cost:=(recipe->>'price')::int;
  if cost is null or cost<0 or cost=0 and recipe->>'source' is distinct from 'drop' then raise exception 'Precio de receta no válido.';end if;
  if (p_args->>'price')::int is distinct from cost then raise exception 'El precio ha cambiado. Consulta de nuevo al maestro.';end if;
  if recipe->>'source'='drop' then raise exception 'Esta receta excepcional no está en venta.';end if;
  if public.game_pelines(d)<cost then raise exception 'NOT_ENOUGH_PELINES';end if;
  d:=public.game_rpg_give(d,public.game_rpg_new_item('receta_'||id,1),false);
  d:=public.game_set_pelines(d,public.game_pelines(d)-cost::int);

 elsif p_action='use_recipe' then
  inv:=public.game_inventory(d);item:=inv->slot;meta:=catalog->'items'->(item->>'id');recipe:=catalog->'recipes'->(meta->>'recipe');
  if recipe is null or item->>'id' is distinct from id or p_args ? 'instanceId' and item->>'instanceId' is distinct from p_args->>'instanceId' then raise exception 'La receta de esa casilla ha cambiado.';end if;
  if public.game_rpg_rank(s,recipe->>'job')<(recipe->>'tier')::int then raise exception 'No tienes el dominio necesario.';end if;
  if s->'learned' ? (recipe->>'id') then raise exception 'Ya conoces esta receta.';end if;
  inv:=jsonb_set(inv,array[slot::text],case when (item->>'count')::int=1 then 'null'::jsonb else item||jsonb_build_object('count',(item->>'count')::int-1) end);
  d:=d||jsonb_build_object('inventory',inv);s:=jsonb_set(s,'{learned}',s->'learned'||to_jsonb(recipe->>'id'));

 elsif p_action='craft' then
  recipe:=catalog->'recipes'->id;job:=recipe->>'job';tier:=(recipe->>'tier')::int;
  if recipe is null or not(s->'learned' ? id) or public.game_rpg_rank(s,job)<tier then raise exception 'Aprende la receta y domina su rango.';end if;
  if not public.game_rpg_near(d,job,w.position) then raise exception 'Acércate al taller de este oficio.';end if;
  amount:=coalesce((p_args->>'count')::int,1);if amount not between 1 and 99 then raise exception 'Cantidad no válida.';end if;
  duration:=(recipe->>'seconds')::numeric*case when d->>'race'='humano' then .85 else 1 end;
  select count(*) into count_jobs from jsonb_array_elements(s->'jobs') j where j->>'job'=job and not (j->>'done')::boolean;
  if duration>0 and count_jobs+amount>5 then raise exception 'Máximo cinco trabajos por oficio.';end if;
  for n in 1..amount loop
   d:=public.game_craft_consume(c.id,d,recipe->'ingredients');
   task:=jsonb_build_object('reservedItems',d->'craftConsumed');d:=d-'craftConsumed';
   s:=s||jsonb_build_object('bankAvailable',public.game_craft_bank(c.id));
   xp:=public.game_rpg_recipe_xp(s,recipe);outitem:=public.game_rpg_new_item(recipe->>'output',(recipe->>'count')::int)||jsonb_build_object('craftedBy',c.id);
   if duration=0 then
    if d->>'race'='elfo' and job='alquimia' and recipe->>'output' like 'pocion_%' and random()<.25 then outitem:=outitem||jsonb_build_object('count',(outitem->>'count')::int+1);end if;
    d:=public.game_rpg_give(d,outitem,false);
    s:=jsonb_set(s,array['xp',job],to_jsonb(coalesce((s->'xp'->>job)::int,0)+xp));s:=jsonb_set(s,array['crafts',job],to_jsonb(coalesce((s->'crafts'->>job)::int,0)+1));
   else
    select greatest(stamp,coalesce(max((j->>'end')::numeric),stamp)) into start_at from jsonb_array_elements(s->'jobs') j where j->>'job'=job and not (j->>'done')::boolean;
    task:=task||jsonb_build_object('id',gen_random_uuid()::text,'recipe',id,'job',job,'start',start_at,'end',start_at+duration,'done',false,'ingredients',recipe->'ingredients','output',outitem,'xp',xp);
    s:=jsonb_set(s,'{jobs}',s->'jobs'||jsonb_build_array(task));
   end if;
  end loop;

 elsif p_action in('cancel','collect','reorder') then
  select value into task from jsonb_array_elements(s->'jobs') where value->>'id'=id;
  if task is null then raise exception 'Ese trabajo ya no está disponible.';end if;job:=task->>'job';
  if not public.game_rpg_near(d,job,w.position) then raise exception 'Acércate a una estación del oficio.';end if;
  if p_action='collect' then
   if not (task->>'done')::boolean then raise exception 'El trabajo no ha terminado.';end if;d:=public.game_rpg_give(d,task->'output',false);
  elsif p_action='cancel' then
   if (task->>'done')::boolean then raise exception 'El trabajo ya ha terminado.';end if;
   if task ? 'reservedItems' then s:=jsonb_set(s,'{deliveries}',(s->'deliveries')||(task->'reservedItems'));
   else for entry in select * from jsonb_each_text(task->'ingredients') loop s:=jsonb_set(s,'{deliveries}',s->'deliveries'||jsonb_build_array(public.game_rpg_new_item(entry.key,entry.value::int)));end loop;end if;
  else
   if (task->>'done')::boolean or (task->>'start')::numeric<=stamp then raise exception 'Solo puedes mover trabajos pendientes.';end if;
  end if;
  select coalesce(jsonb_agg(value order by ord),'[]') into jobs from jsonb_array_elements(s->'jobs') with ordinality as a(value,ord) where value->>'id'<>id;
  if p_action='reorder' then
   select greatest(stamp,coalesce(max((j->>'end')::numeric),stamp)) into start_at from jsonb_array_elements(jobs) j where j->>'job'=job and not (j->>'done')::boolean and (j->>'start')::numeric<=stamp;
   duration:=(task->>'end')::numeric-(task->>'start')::numeric;task:=task||jsonb_build_object('start',start_at,'end',start_at+duration);
   jobs:=jsonb_build_array(task)||jobs;cursor_at:=start_at;
  else cursor_at:=stamp;end if;
  newjobs:='[]';
  for task in select value from jsonb_array_elements(jobs) with ordinality a(value,ord) order by case when value->>'job'<>job or (value->>'done')::boolean then 0 when (value->>'start')::numeric<=stamp then 1 when value->>'id'=id then 2 else 3 end,ord loop
   if task->>'job'=job and not (task->>'done')::boolean then
    duration:=(task->>'end')::numeric-(task->>'start')::numeric;
    if (task->>'start')::numeric>stamp then task:=task||jsonb_build_object('start',cursor_at,'end',cursor_at+duration);end if;
    cursor_at:=(task->>'end')::numeric;
   end if;newjobs:=newjobs||jsonb_build_array(task);
  end loop;s:=jsonb_set(s,'{jobs}',newjobs);

 elsif p_action='delivery' then
  item:=s->'deliveries'->slot;if item is null then raise exception 'El envío no existe.';end if;
  d:=public.game_rpg_give(d,item,false);s:=jsonb_set(s,'{deliveries}',(s->'deliveries')-slot);

 elsif p_action='tool' then
  item:=public.game_inventory(d)->slot;meta:=catalog->'items'->(item->>'id');job:=meta->>'tool';
  if job is null or item->>'count'<>'1' then raise exception 'Selecciona una herramienta.';end if;
  inv:=jsonb_set(public.game_inventory(d),array[slot::text],coalesce(s->'tools'->job,'null'));d:=d||jsonb_build_object('inventory',inv);
  s:=jsonb_set(s,array['tools',job],public.game_rpg_new_item(item->>'id',1)||item);

 elsif p_action='buy_tool' then
  if job not in('minero','lenador','recolector') or not public.game_rpg_near(d,'herreria',w.position) then raise exception 'Acércate al herrero.';end if;
  if public.game_pelines(d)<20 then raise exception 'NOT_ENOUGH_PELINES';end if;
  d:=public.game_set_pelines(d,public.game_pelines(d)-20);d:=public.game_rpg_give(d,public.game_rpg_new_item('herramienta_'||job||'_0',1),false);

 elsif p_action in('gather_start','gather_finish','gather_cancel') then
  if p_action='gather_cancel' then s:=jsonb_set(s,'{gathering}','null');
  else
   meta:=catalog->'nodes'->id;job:=meta->>'job';tier:=(meta->>'tier')::int;rank:=public.game_rpg_rank(s,job);tool:=s->'tools'->job;
   if meta is null or meta->>'location'<>d->>'location' or sqrt(power((w.position->>'x')::numeric-(meta->>'x')::numeric,2)+power((w.position->>'z')::numeric-(meta->>'z')::numeric,2))>3 then raise exception 'Acércate al recurso.';end if;
   if coalesce((tool->>'durability')::numeric,0)<=0 then raise exception 'Equipa o repara la herramienta del oficio.';end if;
   cost:=(array[1,2.5,8,25,70,120]::numeric[])[greatest(0,least(5,tier-rank))+1];
   if (s->>'energy')::numeric<cost then raise exception 'No tienes suficiente energía.';end if;
   if coalesce((s->'nodes'->>id)::numeric,0)>stamp then raise exception 'Este recurso todavía se está recuperando.';end if;
   if p_action='gather_start' then
    s:=jsonb_set(s,'{gathering}',jsonb_build_object('node',id,'start',stamp,'x',w.position->'x','z',w.position->'z','damageAt',d->'combat_at'));
   else
    if s->'gathering'->>'node' is distinct from id or stamp-(s->'gathering'->>'start')::numeric<(meta->>'seconds')::numeric
      or sqrt(power((w.position->>'x')::numeric-(s->'gathering'->>'x')::numeric,2)+power((w.position->>'z')::numeric-(s->'gathering'->>'z')::numeric,2))>.5
      or coalesce((d->>'combat_at')::numeric,0)>(s->'gathering'->>'start')::numeric then raise exception 'La extracción se ha interrumpido.';end if;
    d:=public.game_rpg_give(d,public.game_rpg_new_item(meta->>'item',1),false);
    s:=jsonb_set(s,'{energy}',to_jsonb((s->>'energy')::numeric-cost));
    loss:=.25*(1+greatest(0,tier-rank)*.5)*(1-rank*.03)*(1-(catalog->'items'->(tool->>'id')->>'tier')::int*.04);
    tool:=tool||jsonb_build_object('used',true,'durability',greatest(0,(tool->>'durability')::numeric-loss));s:=jsonb_set(s,array['tools',job],tool);
    s:=jsonb_set(s,array['nodes',id],to_jsonb(stamp+(meta->>'respawn')::numeric));
    s:=jsonb_set(s,array['xp',job],to_jsonb(coalesce((s->'xp'->>job)::int,0)+public.game_rpg_xp(s,job,tier)));
    s:=jsonb_set(s,array['crafts',job],to_jsonb(coalesce((s->'crafts'->>job)::int,0)+1));s:=jsonb_set(s,'{gathering}','null');
    -- Exceptional recipes come only from high-level combat; gathering retains restoration cores.
    if random()<.002 then d:=jsonb_set(d,'{rpg}',s);d:=public.game_rpg_give(d,public.game_rpg_new_item('nucleo_restauracion',1),true);s:=d->'rpg';
    end if;
   end if;
  end if;

 elsif p_action in('repair','restore','restore_item') then
  if not public.game_rpg_near(d,'herreria',w.position) then raise exception 'Acércate al herrero.';end if;tool:=s->'tools'->job;
  if jsonb_typeof(tool) is distinct from 'object' then raise exception 'No hay herramienta equipada.';end if;
  original:=(tool->>'originalDurability')::numeric;max_d:=(tool->>'maxDurability')::numeric;current_d:=(tool->>'durability')::numeric;tier:=(catalog->'items'->(tool->>'id')->>'tier')::int;
  if p_action='repair' then
   fraction:=(max_d-current_d)/max_d;if fraction<=0 then raise exception 'La herramienta ya está reparada.';end if;
   loss:=original*.05*(1-rank*.03)*(1-tier*.04)*fraction;
   if max_d-loss<original*.2 then raise exception 'La herramienta necesita una restauración completa.';end if;
   cost:=ceil((10+10*tier)*fraction);if public.game_pelines(d)<cost then raise exception 'NOT_ENOUGH_PELINES';end if;
   d:=public.game_set_pelines(d,public.game_pelines(d)-cost::int);tool:=tool||jsonb_build_object('maxDurability',max_d-loss,'durability',max_d-loss);
  else
   if max_d=original and current_d=original then raise exception 'La herramienta no necesita restauración.';end if;
   if p_action='restore_item' then d:=public.game_rpg_consume(d,'nucleo_restauracion',1);
   else cost:=5+tier*2;if coalesce((d->'wallet'->>'lagrimas')::int,0)<cost then raise exception 'No tienes suficientes Lágrimas de fénix.';end if;d:=jsonb_set(d,'{wallet,lagrimas}',to_jsonb((d->'wallet'->>'lagrimas')::int-cost::int));end if;
   tool:=tool||jsonb_build_object('maxDurability',original,'durability',original);
  end if;s:=jsonb_set(s,array['tools',job],tool);

 elsif p_action='energy' then
  if (s->>'energy')::numeric>=100 then raise exception 'La energía está llena.';end if;
  if coalesce((d->'wallet'->>'lagrimas')::int,0)<5 then raise exception 'No tienes suficientes Lágrimas de fénix.';end if;
  d:=jsonb_set(d,'{wallet,lagrimas}',to_jsonb((d->'wallet'->>'lagrimas')::int-5));s:=jsonb_set(s,'{energy}','100');

 elsif p_action='enchant' then
  item:=public.game_inventory(d)->slot;meta:=catalog->'items'->(item->>'id');
  if p_args ? 'target' then idx:=(p_args->>'target')::int;if idx not between 0 and 24 or idx=slot then raise exception 'Selecciona un arma válida.';end if;tool:=public.game_inventory(d)->idx;
  else tool:=d->'equipment'->'weapon';end if;
  if meta->>'enchant' is null or public.game_equipment_item(tool->>'id')->>'slot' is distinct from 'weapon' or (public.game_equipment_item(tool->>'id')->>'tier')::int<(meta->>'tier')::int then raise exception 'El arma principal debe ser de calidad igual o superior al pergamino.';end if;
  tool:=tool||jsonb_build_object('instanceId',coalesce(tool->>'instanceId',gen_random_uuid()::text),'enchantment',jsonb_build_object('id',meta->>'enchant','grade',(meta->>'tier')::int));
  d:=public.game_rpg_consume(d,item->>'id',1);
  if p_args ? 'target' then d:=jsonb_set(d,array['inventory',idx::text],tool);else d:=jsonb_set(d,'{equipment,weapon}',tool)-'enchantState';end if;

 elsif p_action='mastery' then
  if not public.game_rpg_near(d,job,w.position) or not(catalog->'professions' ? job) then raise exception 'Acércate al maestro del oficio.';end if;
  next_rank:=coalesce((s->'mastery'->>job)::int,0)+1;
  if next_rank>3 or coalesce((s->'xp'->>job)::int,0)<(array[1500,4000,10000])[next_rank] or coalesce((s->'crafts'->>job)::int,0)<next_rank*50 then raise exception 'Faltan experiencia o prácticas para este proyecto de maestría.';end if;
  mat:=case when job in('minero','herreria','joyeria') then 'minero' when job in('lenador','carpinteria','ebanisteria') then 'lenador' else 'recolector' end;
  d:=public.game_rpg_consume(d,'material_'||mat||'_0',next_rank*20);d:=public.game_rpg_consume(d,'material_'||mat||'_'||(next_rank+1)::text,next_rank*10);
  s:=jsonb_set(s,array['mastery',job],to_jsonb(next_rank));

 elsif p_action='place' then
  item:=public.game_inventory(d)->slot;meta:=catalog->'items'->(item->>'id');
  if meta->>'furniture' is null or d->>'location'<>'casa_de_isberto_interior' or d->>'shadowQuest' is distinct from 'returned' then raise exception 'Este mueble requiere una casa habilitada.';end if;
  if jsonb_array_length(s->'furniture')>=30 then raise exception 'Máximo treinta muebles colocados.';end if;
  if meta->>'furniture'='estacion' and not(catalog->'professions' ? job) then raise exception 'Selecciona el oficio de la estación.';end if;
  yaw:=coalesce((p_args->>'yaw')::numeric,0);px:=(w.position->>'x')::numeric+sin(yaw)*1.8;pz:=(w.position->>'z')::numeric+cos(yaw)*1.8;
  if not public.game_rpg_sight(d->>'location',(w.position->>'x')::numeric,(w.position->>'z')::numeric,px,pz) or not public.game_rpg_sight(d->>'location',px-.9,pz,px+.9,pz) or not public.game_rpg_sight(d->>'location',px,pz-.6,px,pz+.6) or exists(select 1 from jsonb_array_elements(s->'furniture') f where f->>'location'=d->>'location' and sqrt(power((f->>'x')::numeric-px,2)+power((f->>'z')::numeric-pz,2))<1.8) then raise exception 'Busca un espacio despejado delante del personaje.';end if;
  s:=jsonb_set(s,'{furniture}',s->'furniture'||jsonb_build_array(jsonb_build_object('id',gen_random_uuid()::text,'item',item,'location',d->>'location','x',px,'z',pz,'yaw',yaw,'job',case when meta->>'furniture'='estacion' then job else null end)));
  d:=public.game_remove_item(d,slot);
 elsif p_action='pickup' then
  select value into item from jsonb_array_elements(s->'furniture') where value->>'id'=id;
  if item is null or item->>'location'<>d->>'location' or sqrt(power((w.position->>'x')::numeric-(item->>'x')::numeric,2)+power((w.position->>'z')::numeric-(item->>'z')::numeric,2))>4 then raise exception 'Acércate al mueble.';end if;
  d:=public.game_rpg_give(d,item->'item',false);select coalesce(jsonb_agg(value),'[]') into jobs from jsonb_array_elements(s->'furniture') where value->>'id'<>id;s:=jsonb_set(s,'{furniture}',jobs);
 else raise exception 'Acción de oficio no válida.';end if;

 select coalesce(jsonb_agg(value),'[]') into receipt from (select value from jsonb_array_elements(coalesce(s->'requests','[]')) with ordinality a(value,ord) order by ord desc limit 255) a;
 s:=s||jsonb_build_object('revision',p_revision+1,'requests',receipt||to_jsonb(p_request::text));d:=d||jsonb_build_object('rpg',s);
 -- Inventory changes invalidate accepted offers; both participants must review again.
 update public.player_trades set revision=revision+1,accepted_a=false,accepted_b=false,offer_a=case when a=c.id then '{"items":[],"pelines":0}'::jsonb else offer_a end,offer_b=case when b=c.id then '{"items":[],"pelines":0}'::jsonb else offer_b end where status in('open','invited') and c.id in(a,b);
 d:=public.game_profession_tutorial_event(d,p_action,p_args,c.data);
 return public.game_store(c.id,d);
end $$;
create or replace function public.game_rpg_near(d jsonb,job text,pos jsonb) returns boolean language sql immutable set search_path='' as $$
 select exists(select 1 from jsonb_each(public.game_rpg_catalog()->'stations') s where (s.value->>'job'=job or job in('minero','lenador','recolector') and s.value->>'job'='herreria') and s.value->>'location'=coalesce(d->>'location','brumaluz') and sqrt(power((pos->>'x')::numeric-(s.value->>'x')::numeric,2)+power((pos->>'z')::numeric-(s.value->>'z')::numeric,2))<=coalesce((s.value->>'radius')::numeric,4))
 or (nullif(d->'rpg'->'homes'->>'visit','') is null and exists(select 1 from jsonb_array_elements(coalesce(d->'rpg'->'furniture','[]')) f where f->>'job'=job and f->>'location'=d->>'location' and sqrt(power((pos->>'x')::numeric-(f->>'x')::numeric,2)+power((pos->>'z')::numeric-(f->>'z')::numeric,2))<=4))
$$;
create or replace function public.game_rpg_settle(d jsonb,stamp numeric) returns jsonb language plpgsql volatile set search_path='' as $$
declare s jsonb:=coalesce(d->'rpg','{}'); jobs jsonb:='[]';task jsonb;job text; slot text;item jsonb;inv jsonb;eq jsonb;extras jsonb:='[]';copy jsonb;
begin
 s:='{"version":1,"energy":100,"xp":{},"mastery":{},"learned":[],"tools":{},"jobs":[],"deliveries":[],"nodes":{},"gathering":null,"crafts":{},"projects":{},"furniture":[]}'::jsonb||s;
 s:=public.game_craft_clock(s,stamp);
 if s->'dailyOrders'->>'day' is distinct from to_char(to_timestamp(stamp) at time zone 'UTC','YYYY-MM-DD') then s:=s||jsonb_build_object('dailyOrders',jsonb_build_object('day',to_char(to_timestamp(stamp) at time zone 'UTC','YYYY-MM-DD'),'completed',0,'accepted','[]'::jsonb));end if;
 s:=s||jsonb_build_object('energy',least(100,coalesce((s->>'energy')::numeric,100)+greatest(0,stamp-coalesce((s->>'at')::numeric,stamp))*100/16560),'at',stamp);
 for task in select value from jsonb_array_elements(s->'jobs') order by (value->>'end')::numeric loop
  if not coalesce((task->>'done')::boolean,false) and (task->>'end')::numeric<=stamp then
   job:=task->>'job';task:=task||jsonb_build_object('done',true,'output',task->'output'||jsonb_build_object('craftedBy',s->>'owner'));
   s:=jsonb_set(s,array['xp',job],to_jsonb(coalesce((s->'xp'->>job)::int,0)+public.game_rpg_recipe_xp(s,public.game_rpg_catalog()->'recipes'->(task->>'recipe'))));
   s:=jsonb_set(s,array['crafts',job],to_jsonb(coalesce((s->'crafts'->>job)::int,0)+1));
  end if;jobs:=jobs||jsonb_build_array(task);
 end loop;
 s:=s||jsonb_build_object('jobs',jobs);d:=d||jsonb_build_object('rpg',s);
 inv:=public.game_inventory(d);eq:=coalesce(d->'equipment','{}');
 for i in 0..24 loop
  item:=inv->i;
  if jsonb_typeof(item)='object' and (public.game_equipment_item(item->>'id') is not null or public.game_rpg_stack_limits()->>(item->>'id')='1') then
   for j in 2..greatest(1,coalesce((item->>'count')::int,1)) loop
    extras:=extras||jsonb_build_array(public.game_rpg_new_item(item->>'id',1)||(item-'instanceId')||jsonb_build_object('count',1));
   end loop;
   if not(item ? 'instanceId') then item:=public.game_rpg_new_item(item->>'id',1)||item;end if;
   inv:=jsonb_set(inv,array[i::text],item||jsonb_build_object('count',1));
  end if;
 end loop;
 foreach slot in array array['head','chest','hands','legs','weapon','offhand','ring','pendant','trinket'] loop
  item:=eq->slot;if jsonb_typeof(item)='object' and not(item ? 'instanceId') then eq:=jsonb_set(eq,array[slot],public.game_rpg_new_item(item->>'id',1)||item);end if;
 end loop;
 d:=d||jsonb_build_object('inventory',inv,'equipment',eq);
 for copy in select value from jsonb_array_elements(extras) loop d:=public.game_rpg_give(d,copy,true);end loop;
 return d;
end $$;
create or replace function public.game_stack_into(p_slots jsonb,p_item jsonb) returns jsonb language plpgsql immutable set search_path='' as $$
declare slots jsonb:=p_slots; item jsonb; remaining int:=(p_item->>'count')::int; cap int:=greatest(coalesce((public.game_item(p_item->>'id')->>'stack')::int,50),1); n int;i int;
begin
 if p_item ? 'instanceId' then cap:=1;end if;
 if cap>1 then
  for i in 0..jsonb_array_length(slots)-1 loop
   item:=slots->i;
   if jsonb_typeof(item)='object' and (item-'count'-'bound')=(p_item-'count'-'bound') and coalesce((item->>'bound')::boolean,false)=coalesce((p_item->>'bound')::boolean,false) then
    n:=least(remaining,greatest(0,cap-(item->>'count')::int));remaining:=remaining-n;slots:=jsonb_set(slots,array[i::text],item||jsonb_build_object('count',(item->>'count')::int+n));
   end if;
  end loop;
 end if;
 for i in 0..jsonb_array_length(slots)-1 loop
  exit when remaining<=0;
  if jsonb_typeof(slots->i) is distinct from 'object' then n:=least(cap,remaining);slots:=jsonb_set(slots,array[i::text],p_item||jsonb_build_object('count',n));remaining:=remaining-n;end if;
 end loop;
 if remaining>0 then return null;end if;return slots;
end $$;
create or replace function public.game_store(p_id uuid, d jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  result jsonb;
begin
  d:=jsonb_set(d,'{rpg}',coalesce(d->'rpg','{}')||jsonb_build_object('owner',p_id));
  d := public.game_rpg_settle(d,extract(epoch from clock_timestamp()));
  d := public.game_food_data(p_id,d);
  d := public.game_regen_data(p_id,d);
  d := d || jsonb_build_object(
    'overheal', case when coalesce((d ->> 'health')::int, -1) = 0 then 0 else public.game_overheal_now(d) end,
    'overheal_at', extract(epoch from now())
  );
  d:=d||jsonb_build_object('serverRevision',coalesce((select (data->>'serverRevision')::bigint from public.characters where id=p_id),0)+1);
  update public.characters set data = d - 'partyPeers', updated_at = now() where id = p_id returning data into result;
  return public.game_party_data(p_id,result);
end;
$$;
create or replace function public.game_bank_spot(p_location text)
returns jsonb language sql immutable set search_path='' as $$
  select case p_location
    when 'habitacion_posada_lucero_del_alba' then '{"x":-1.9,"z":1.5,"radius":2.2}'::jsonb
    when 'casa_del_olmo' then '{"x":2.6,"z":2.6,"radius":2.2}'::jsonb
    when 'casa_de_isberto_interior' then '{"x":2.25,"z":3.25,"radius":3}'::jsonb
  end
$$;
create or replace function public.bank_action(p_character_id uuid,p_action text,p_slot int default null,
  p_expected jsonb default null,p_amount int default null,p_target int default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
  c public.characters; d jsonb; bank public.account_banks; inv jsonb; bank_items jsonb; source jsonb; merged jsonb;
  pos jsonb; spot jsonb; changed boolean:=false; placed jsonb; rest jsonb;
begin
  -- Mismo orden de bloqueo que trade_action y move_inventory_item.
  perform pg_catalog.pg_advisory_xact_lock(731029,3);
  c:=public.game_lock_character(p_character_id);
  d:=c.data;
  if p_action is null or p_action not in ('open','deposit','withdraw','move','deposit_pelines','withdraw_pelines')
    then raise exception 'BANK_INVALID_ACTION'; end if;
  if public.game_health(d)=0 then raise exception 'BANK_DEAD'; end if;
  select position into pos from public.world_players where character_id=c.id and user_id=c.user_id
    and seen_at>now()-interval '15 seconds';
  spot:=public.game_bank_spot(coalesce(d->>'location','brumaluz'));
  if d->>'location' in ('habitacion_posada_lucero_del_alba','casa_del_olmo') and (nullif(d->'rpg'->'homes'->>'visit','') is not null or d->>'location'='casa_del_olmo' and not coalesce(d->'rpg'->'homes'->'owned' ? 'olmo',false)) then raise exception 'Abre el cofre desde tu propia vivienda.';end if;
  if pos is null or spot is null then raise exception 'BANK_NOT_PLAYING'; end if;
  if power((pos->>'x')::numeric-(spot->>'x')::numeric,2)+power((pos->>'z')::numeric-(spot->>'z')::numeric,2)
    >power((spot->>'radius')::numeric,2) then raise exception 'BANK_TOO_FAR'; end if;

  insert into public.account_banks(user_id) values (c.user_id) on conflict (user_id) do nothing;
  perform public.game_deliver_modular_parts(c.user_id);
  select * into bank from public.account_banks where user_id=c.user_id for update;
  insert into public.equipment_modular_migrations(scope,owner,original) values('bank',c.user_id,bank.items) on conflict do nothing;
  bank_items:=public.game_bank_items(bank.items,bank.size);
  inv:=public.game_inventory(d);

  if p_action='deposit' then
    if p_slot is null or p_slot not between 0 and 24 then raise exception 'INVALID_ITEM'; end if;
    source:=inv->p_slot;
    if jsonb_typeof(source) is distinct from 'object' or jsonb_typeof(p_expected) is distinct from 'object'
      or source->>'id' is distinct from p_expected->>'id'
      or source->>'count' is distinct from p_expected->>'count'
      or coalesce((source->>'bound')::boolean,false) is distinct from coalesce((p_expected->>'bound')::boolean,false)
      then raise exception 'INVENTORY_CHANGED'; end if;
    if coalesce((source->>'bound')::boolean,false) or coalesce((public.game_item(source->>'id')->>'bound')::boolean,false)
      then raise exception 'BANK_ITEM_BOUND'; end if;
    if p_target is null then
      merged:=public.game_stack_into(bank_items,source);
      if merged is null then raise exception 'BANK_FULL'; end if;
      bank_items:=merged; inv:=jsonb_set(inv,array[p_slot::text],'null'::jsonb);
    else
      if p_target<0 or p_target>=bank.size then raise exception 'INVALID_ITEM'; end if;
      placed:=public.game_place_item(bank_items,p_target,source);
      bank_items:=placed->'slots'; rest:=placed->'rest';
      inv:=jsonb_set(inv,array[p_slot::text],coalesce(rest,'null'::jsonb));
    end if;
    changed:=true;
  elsif p_action='withdraw' then
    if p_slot is null or p_slot<0 or p_slot>=bank.size then raise exception 'INVALID_ITEM'; end if;
    source:=bank_items->p_slot;
    if jsonb_typeof(source) is distinct from 'object' or jsonb_typeof(p_expected) is distinct from 'object'
      or source->>'id' is distinct from p_expected->>'id'
      or source->>'count' is distinct from p_expected->>'count'
      or coalesce((source->>'bound')::boolean,false) is distinct from coalesce((p_expected->>'bound')::boolean,false)
      then raise exception 'BANK_CHANGED'; end if;
    if p_target is null then
      merged:=public.game_stack_into(inv,source);
      if merged is null then raise exception 'INVENTORY_FULL'; end if;
      inv:=merged; bank_items:=jsonb_set(bank_items,array[p_slot::text],'null'::jsonb);
    else
      if p_target not between 0 and 24 then raise exception 'INVALID_ITEM'; end if;
      placed:=public.game_place_item(inv,p_target,source);
      rest:=placed->'rest';
      -- Lo que había en la mochila pasa al baúl: no puede estar ligado.
      if jsonb_typeof(rest)='object' and (coalesce((rest->>'bound')::boolean,false)
        or coalesce((public.game_item(rest->>'id')->>'bound')::boolean,false)) then raise exception 'BANK_ITEM_BOUND'; end if;
      inv:=placed->'slots';
      bank_items:=jsonb_set(bank_items,array[p_slot::text],coalesce(rest,'null'::jsonb));
    end if;
    changed:=true;
  elsif p_action='move' then
    if p_slot is null or p_target is null or p_slot<0 or p_slot>=bank.size or p_target<0 or p_target>=bank.size
      or p_slot=p_target then raise exception 'INVALID_ITEM'; end if;
    source:=bank_items->p_slot;
    if jsonb_typeof(source) is distinct from 'object' or jsonb_typeof(p_expected) is distinct from 'object'
      or source->>'id' is distinct from p_expected->>'id'
      or source->>'count' is distinct from p_expected->>'count'
      then raise exception 'BANK_CHANGED'; end if;
    placed:=public.game_place_item(jsonb_set(bank_items,array[p_slot::text],'null'::jsonb),p_target,source);
    bank_items:=jsonb_set(placed->'slots',array[p_slot::text],coalesce(placed->'rest','null'::jsonb));
    changed:=true;
  elsif p_action='deposit_pelines' then
    if p_amount is null or p_amount<=0 then raise exception 'BANK_INVALID_ACTION'; end if;
    if public.game_pelines(d)<p_amount then raise exception 'NOT_ENOUGH_MONEY'; end if;
    d:=public.game_set_pelines(d,public.game_pelines(d)-p_amount);
    bank.pelines:=bank.pelines+p_amount; changed:=true;
  elsif p_action='withdraw_pelines' then
    if p_amount is null or p_amount<=0 then raise exception 'BANK_INVALID_ACTION'; end if;
    if bank.pelines<p_amount then raise exception 'BANK_NOT_ENOUGH_MONEY'; end if;
    d:=public.game_set_pelines(d,public.game_pelines(d)+p_amount);
    bank.pelines:=bank.pelines-p_amount; changed:=true;
  end if;

  if changed then
    update public.account_banks set items=bank_items,pelines=bank.pelines,updated_at=now() where user_id=c.user_id;
    -- Igual que move_inventory_item: cualquier cambio invalida las ofertas de intercambio abiertas.
    update public.player_trades set revision=revision+1,accepted_a=false,accepted_b=false,
      offer_a=case when a=c.id then '{"items":[],"pelines":0}'::jsonb else offer_a end,
      offer_b=case when b=c.id then '{"items":[],"pelines":0}'::jsonb else offer_b end
      where status in ('invited','open') and c.id in(a,b);
    d:=d||jsonb_build_object('inventory',inv);
  end if;
  return public.game_store(c.id,d)||jsonb_build_object('bank',jsonb_build_object('items',bank_items,'pelines',bank.pelines,'size',bank.size));
end $$;
create or replace function public.world_travel(p_character_id uuid, p_session_id uuid, p_portal text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  c public.characters;
  w public.world_players;
  p public.world_portals;
  here text;
  distance double precision;
begin
  if uid is null then raise exception 'NOT_AUTHENTICATED'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(uid::text, 1));
  c := public.game_lock_character(p_character_id);
  select * into w from public.world_players where user_id = uid for update;
  if w.session_id is distinct from p_session_id or w.character_id is distinct from c.id then
    raise exception 'WORLD_SESSION_REPLACED';
  end if;
  if w.seen_at < now() - interval '15 seconds' then raise exception 'WORLD_SESSION_REPLACED'; end if;
  if public.game_health(c.data) = 0 or w.dead then raise exception 'CHARACTER_DEAD'; end if;
  if public.game_wilderness_in_combat(c.id) then raise exception 'IN_COMBAT';end if;
  if c.data -> 'combatEncounter' ->> 'status' = 'active'
    and coalesce((c.data->'combatEncounter'->>'engaged')::boolean,
      (c.data->'combatEncounter'->>'health')::numeric<(c.data->'combatEncounter'->>'maxHealth')::numeric,false)
    then raise exception 'IN_COMBAT'; end if;
  here := coalesce(c.data ->> 'location', 'brumaluz');
  select * into p from public.world_portals where map = here and id = p_portal;
  if not found then raise exception 'PORTAL_NOT_FOUND'; end if;
  -- La casa de Isberto está cerrada hasta que él invita al jugador (los personajes anteriores a la historia, siempre abierta).
  if p.target_map = 'casa_de_isberto_interior' and not public.game_isberto_house_open(c.data) then raise exception 'PORTAL_LOCKED'; end if;
  if p.target_map='casa_del_olmo' then
    if not public.game_home_owned(c.data,'olmo') and public.game_home_owner(c.id,c.data||jsonb_build_object('location',p.target_map))=c.id then raise exception 'Esta casa todavía no te pertenece. Consulta Mis viviendas.';end if;
  end if;
  distance := sqrt(power((w.position ->> 'x')::double precision - p.x, 2) + power((w.position ->> 'z')::double precision - p.z, 2));
  if distance is null or distance > p.radius + 0.5 then raise exception 'PORTAL_TOO_FAR'; end if;
  if not public.game_location_contains(p.target_map, (p.target ->> 'x')::double precision, (p.target ->> 'z')::double precision) then
    raise exception 'INVALID_WORLD_STATE';
  end if;
  if nullif(c.data->'rpg'->'homes'->>'visit','') is not null and (here in ('habitacion_posada_lucero_del_alba','casa_del_olmo') or coalesce(c.data->'rpg'->'homes'->>'visitHome','lucero') is distinct from case p.target_map when 'habitacion_posada_lucero_del_alba' then 'lucero' when 'casa_del_olmo' then 'olmo' end) then
    c.data:=jsonb_set(c.data,'{rpg,homes}',(c.data->'rpg'->'homes')-'visit'-'visitHome');
  end if;
  c.data := public.game_store(c.id, c.data || jsonb_build_object(
    'location', p.target_map, 'position', p.target, 'position_at', extract(epoch from now())));
  update public.world_players set position = p.target,
    facing = coalesce((p.target ->> 'yaw')::double precision, 0) + pi(), jump = 0,
    movement_credit = 3, seen_at = now(), saved_at = now()
    where user_id = uid;
  return jsonb_build_object('status', 'ok', 'location', p.target_map, 'position', p.target,
    'players', public.game_world_snapshot(uid),
    'encounter', c.data -> 'combatEncounter',
    'vitals', public.game_public_vitals(c.data),
    'food', jsonb_build_object('buff', c.data -> 'foodBuff', 'revision', c.data -> 'foodRevision', 'at', c.data -> 'food_at'),
    'clock', public.world_clock(),'wilderness',public.game_wilderness_view(c.id));
end;
$$;
